  return blocks.filter((b) => b.type === "text").map((b: any) => b.text).join("\n").trim();
}
function thinkingOf(blocks: Anthropic.Messages.ContentBlock[]): string {
  return blocks.filter((b) => b.type === "thinking").map((b: any) => b.thinking || "").join("\n").trim();
